"""Trie-based hierarchical metrics aggregation.

Collects counters, gauges, and histograms keyed by dot-separated metric names
(e.g. ``"http.requests.total"``).  Each trie node aggregates the metrics of
its subtree, so ``range_query`` over a prefix is efficient.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Any


# ---------------------------------------------------------------------------
# Metric types
# ---------------------------------------------------------------------------

class MetricType(Enum):
    """Supported metric types."""
    COUNTER = "counter"
    GAUGE = "gauge"
    HISTOGRAM = "histogram"


@dataclass
class Counter:
    """Monotonically increasing counter."""
    value: float = 0.0

    def update(self, amount: float) -> None:
        self.value += amount

    def snapshot(self) -> dict[str, Any]:
        return {"type": "counter", "value": self.value}


@dataclass
class Gauge:
    """Gauge that can go up or down; stores the latest value."""
    value: float = 0.0

    def update(self, amount: float) -> None:
        self.value = amount

    def snapshot(self) -> dict[str, Any]:
        return {"type": "gauge", "value": self.value}


@dataclass
class Histogram:
    """Histogram with fixed bucket boundaries.

    Default buckets suit latency measurements in milliseconds.  Pass
    custom ``boundaries`` for other ranges.
    """
    boundaries: tuple[float, ...] = (1, 5, 10, 25, 50, 100, 250, 500, 1000)
    buckets: list[int] = field(default_factory=list)
    count: int = 0
    sum: float = 0.0

    def __post_init__(self) -> None:
        if not self.buckets:
            self.buckets = [0] * (len(self.boundaries) + 1)

    def update(self, value: float) -> None:
        self.count += 1
        self.sum += value
        for i, boundary in enumerate(self.boundaries):
            if value <= boundary:
                self.buckets[i] += 1
                return
        self.buckets[-1] += 1  # overflow bucket

    def snapshot(self) -> dict[str, Any]:
        return {
            "type": "histogram",
            "count": self.count,
            "sum": self.sum,
            "mean": self.sum / self.count if self.count else 0.0,
            "buckets": dict(zip(
                [str(b) for b in self.boundaries] + ["+Inf"],
                self.buckets,
            )),
        }


# Aggregation accumulator used during range_query.
@dataclass
class _AggResult:
    counters: dict[str, float] = field(default_factory=dict)
    gauges: dict[str, float] = field(default_factory=dict)
    histograms: dict[str, Histogram] = field(default_factory=dict)

    def merge_counter(self, name: str, c: Counter) -> None:
        self.counters[name] = self.counters.get(name, 0.0) + c.value

    def merge_gauge(self, name: str, g: Gauge) -> None:
        self.gauges[name] = self.gauges.get(name, 0.0) + g.value

    def merge_histogram(self, name: str, h: Histogram) -> None:
        if name not in self.histograms:
            self.histograms[name] = Histogram(boundaries=h.boundaries)
        agg = self.histograms[name]
        agg.count += h.count
        agg.sum += h.sum
        for i in range(len(agg.buckets)):
            agg.buckets[i] += h.buckets[i]


# ---------------------------------------------------------------------------
# TrieNode
# ---------------------------------------------------------------------------

class TrieNode:
    """A trie node that stores hierarchical metrics.

    Metric names are split on ``"."``; each segment becomes a child link.
    Leaf nodes hold the actual metric values while every node in the path
    maintains an aggregate of its subtree for fast ``range_query``.

    Args:
        separator: Delimiter used to split metric names (default ``"."``).

    Example::

        root = TrieNode()
        root.insert("http.requests.total", 1, MetricType.COUNTER)
        root.insert("http.requests.total", 3, MetricType.COUNTER)
        root.insert("http.latency.p99", 42.5, MetricType.GAUGE)

        snap = root.range_query("http.")
        # snap.counters == {"http.requests.total": 4.0}
        # snap.gauges   == {"http.latency.p99": 42.5}
    """

    __slots__ = ("children", "counters", "gauges", "histograms", "_separator")

    def __init__(self, separator: str = ".") -> None:
        self.children: dict[str, TrieNode] = {}
        self.counters: dict[str, Counter] = {}
        self.gauges: dict[str, Gauge] = {}
        self.histograms: dict[str, Histogram] = {}
        self._separator = separator

    # ------------------------------------------------------------------
    # Core operations
    # ------------------------------------------------------------------

    def insert(
        self,
        name: str,
        value: float,
        metric_type: MetricType,
        *,
        boundaries: tuple[float, ...] | None = None,
    ) -> None:
        """Insert a metric value into the trie.

        Args:
            name: Dot-separated metric name (e.g. ``"cpu.usage"``).
            value: Numeric value.  For counters this is the *delta* to add;
                for gauges it is the new absolute value; for histograms it is
                an observation to record.
            metric_type: One of ``MetricType.COUNTER``, ``GAUGE``, or
                ``HISTOGRAM``.
            boundaries: Custom histogram bucket boundaries.  Only used when
                *metric_type* is ``HISTOGRAM`` and the metric is created for
                the first time.
        """
        parts = name.split(self._separator)
        node = self
        for part in parts:
            if part not in node.children:
                node.children[part] = TrieNode(separator=self._separator)
            node = node.children[part]

        if metric_type is MetricType.COUNTER:
            if name not in node.counters:
                node.counters[name] = Counter()
            node.counters[name].update(value)
        elif metric_type is MetricType.GAUGE:
            if name not in node.gauges:
                node.gauges[name] = Gauge()
            node.gauges[name].update(value)
        elif metric_type is MetricType.HISTOGRAM:
            if name not in node.histograms:
                node.histograms[name] = Histogram(
                    boundaries=boundaries or Histogram().boundaries,
                )
            node.histograms[name].update(value)

    def delete(self, name: str) -> bool:
        """Remove a metric entirely from the trie.

        Args:
            name: The full dot-separated metric name to delete.

        Returns:
            ``True`` if the metric was found and removed, ``False`` otherwise.
        """
        parts = name.split(self._separator)
        path: list[tuple[TrieNode, str]] = []
        node = self
        for part in parts:
            if part not in node.children:
                return False
            path.append((node, part))
            node = node.children[part]

        removed = False
        if name in node.counters:
            del node.counters[name]
            removed = True
        if name in node.gauges:
            del node.gauges[name]
            removed = True
        if name in node.histograms:
            del node.histograms[name]
            removed = True

        if not removed:
            return False

        # Prune empty leaf nodes bottom-up.
        for parent, key in reversed(path):
            child = parent.children[key]
            if (
                not child.children
                and not child.counters
                and not child.gauges
                and not child.histograms
            ):
                del parent.children[key]
            else:
                break

        return True

    def range_query(self, prefix: str) -> dict[str, Any]:
        """Aggregate all metrics whose name starts with *prefix*.

        Args:
            prefix: A dot-separated prefix (e.g. ``"http."``).  An empty
                string matches every metric in the trie.

        Returns:
            A dict with three keys:

            - ``"counters"`` – ``{name: summed_value, ...}``
            - ``"gauges"`` – ``{name: latest_value, ...}``
            - ``"histograms"`` – ``{name: merged_histogram_snapshot, ...}``
        """
        agg = _AggResult()
        node = self._find(prefix)
        if node is not None:
            self._collect(node, prefix, agg)
        return {
            "counters": agg.counters,
            "gauges": agg.gauges,
            "histograms": {
                name: h.snapshot() for name, h in agg.histograms.items()
            },
        }

    # ------------------------------------------------------------------
    # Introspection helpers
    # ------------------------------------------------------------------

    def get(self, name: str) -> dict[str, Any] | None:
        """Return the raw snapshot for a single metric, or ``None``."""
        parts = name.split(self._separator)
        node = self
        for part in parts:
            if part not in node.children:
                return None
            node = node.children[part]
        if name in node.counters:
            return node.counters[name].snapshot()
        if name in node.gauges:
            return node.gauges[name].snapshot()
        if name in node.histograms:
            return node.histograms[name].snapshot()
        return None

    def __len__(self) -> int:
        """Total number of distinct metrics stored."""
        total = len(self.counters) + len(self.gauges) + len(self.histograms)
        for child in self.children.values():
            total += len(child)
        return total

    def __bool__(self) -> bool:
        return bool(self.children or self.counters or self.gauges or self.histograms)

    # ------------------------------------------------------------------
    # Internal helpers
    # ------------------------------------------------------------------

    def _find(self, prefix: str) -> TrieNode | None:
        node = self
        if prefix:
            for part in prefix.split(self._separator):
                if part not in node.children:
                    return None
                node = node.children[part]
        return node

    def _collect(self, node: TrieNode, prefix: str, agg: _AggResult) -> None:
        for name, counter in node.counters.items():
            agg.merge_counter(name, counter)
        for name, gauge in node.gauges.items():
            agg.merge_gauge(name, gauge)
        for name, hist in node.histograms.items():
            agg.merge_histogram(name, hist)
        for segment, child in node.children.items():
            self._collect(child, prefix + segment + self._separator, agg)


# ---------------------------------------------------------------------------
# Demo
# ---------------------------------------------------------------------------

if __name__ == "__main__":
    root = TrieNode()

    # Counters
    root.insert("http.requests.total", 1, MetricType.COUNTER)
    root.insert("http.requests.total", 3, MetricType.COUNTER)
    root.insert("http.errors.5xx", 2, MetricType.COUNTER)

    # Gauges
    root.insert("cpu.usage", 73.5, MetricType.GAUGE)
    root.insert("cpu.usage", 81.0, MetricType.GAUGE)  # overwrites
    root.insert("mem.free_mb", 4096, MetricType.GAUGE)

    # Histogram
    root.insert("http.latency", 12, MetricType.HISTOGRAM)
    root.insert("http.latency", 45, MetricType.HISTOGRAM)
    root.insert("http.latency", 200, MetricType.HISTOGRAM)

    print("=== single metric lookups ===")
    print("  http.requests.total ->", root.get("http.requests.total"))
    print("  cpu.usage           ->", root.get("cpu.usage"))
    print("  http.latency        ->", root.get("http.latency"))

    print(f"\ntotal metrics: {len(root)}")

    print("\n=== range_query('http.') ===")
    import json
    result = root.range_query("http.")
    print(json.dumps(result, indent=2))

    print("\n=== range_query('') (all) ===")
    result = root.range_query("")
    print(json.dumps(result, indent=2))

    print("\n=== delete http.errors.5xx ===")
    print("  deleted:", root.delete("http.errors.5xx"))
    print("  deleted again:", root.delete("http.errors.5xx"))
    print("  total metrics after delete:", len(root))

    print("\n=== range_query('http.') after delete ===")
    result = root.range_query("http.")
    print(json.dumps(result, indent=2))

